custom_css:
/* ============================================================
   冰山之下 @Mayonnaise
   非常感谢导航楼内各位老师的分享，所使用代码已在以下标注作者❤︎
   ============================================================ */

@import url("https://fontsapi.zeoseven.com/301/main/result.css");

body {
    font-family: "GenWanMin2 TC R";
    font-weight: normal;
}

:root {
    --screenwitdh: 387px;/* 自定义宽度 */
    --height: 115px;/* 自定义高度 */
}

::-webkit-scrollbar {
    display: none;
}

::selection {
    background: var(--SmartThemeQuoteColor);
    color: #fff;
}

/* ============================================================
   2. 聊天区域与消息背景 (Chat Area & Message Backgrounds)
   ============================================================ */
#chat {
    background: transparent;
    backdrop-filter: none;
    margin-left: 14px;
    margin-right: 14px;
    border: none;
}

.mes {
    background-image: url("https://www.transparenttextures.com/patterns/rough-cloth-light.png");
    margin-top: 25px;
    margin-bottom: 25px;
    background-color: var(--SmartThemeChatTintColor);
}

[is_user="false"].mes {
    margin-top: var(--height);
    background-image: 
        linear-gradient(to bottom, rgba(28, 28, 28, 1) 10%, transparent 100%),
        url("https://www.transparenttextures.com/patterns/rough-cloth-light.png");
    background-size: 
        var(--screenwitdh) 90px,
        auto;
    background-position: 
        center top,
        0 0;
    background-repeat: 
        no-repeat,
        repeat;
}

[is_user="false"].mes::before {
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E5%86%B0%E5%B1%B1%E4%B9%8B%E4%B8%8B/2.png');
    background-repeat: no-repeat;
    background-position: center top;
    background-size: contain;
    position: absolute;
    width: var(--screenwitdh);
    height: var(--height); 
    top: calc(var(--height) * -1);                        
    left: 50%;
    transform: translateX(-50%);
    pointer-events: none;
}

.last_mes{
  margin-bottom: 35px!important;
}

/* ============================================================
   3. 消息文本与内容装饰 (Message Text & Decorations)
   ============================================================ */
.mes .name_text {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    font-size: 18px;
    top: -2px;
}

[is_user="false"] .name_text {
    color: rgba(198, 198, 198, 1);
}

.mes_text code, pre {
    font-family: "GenWanMin2 TC R";
    padding: 2px;
    border-radius: 0;
    background: rgba(0, 0, 0, 1);
    border: 0;
    color: rgba(130, 130, 130, 1);
    font-size: 14px;
}

.mes_text q {
    background: linear-gradient(
        to right,
        transparent 0%,
        color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 85%) 20%,
        color-mix(in srgb, var(--SmartThemeQuoteColor), transparent 85%) 80%,
        transparent 100%
    ) !important;
}

.mes_block {
    padding: 70px 10px 30px 10px;
    position: relative !important;
}

.mes_text::after {
    content: '';
    border-bottom: 1px solid rgba(102, 102, 102, 1);
    margin-top: 10px;
    display: block;
}

.mes_text {
    padding: 8px;
}

.mes_reasoning {
    color: rgba(109, 109, 109, 1);
}

.mes_reasoning_header.flex-container {
    background: rgba(66, 66, 66, 1);
    border: 1px solid rgba(85, 85, 85, 1);
    padding: 3px;
    border-radius: 0;
    color: rgba(157, 157, 157, 1);
    left: 5px;
    transition: 0.3s ease;
}

.mes_reasoning_header.flex-container span,
.mes_reasoning_header.flex-container .fa-solid {
    display: none !important;
}

.mes_reasoning_header.flex-container::before {
    content: "[REDACTED]";
    font-family: "GenWanMin2 TC R";
    font-weight: bold;
    font-size: var(--mainFontFamily);
}

.mes_reasoning_details[open] .mes_reasoning_header.flex-container {
    background: rgba(34, 34, 34, 1) !important;
    color: rgba(192, 192, 192, 1);
}

.mes_reasoning_header.flex-container {
    transition: background 0.8s ease-in-out;
}

/* ============================================================
   4. 消息元数据与文件信息 (Message Metadata & File Info)
   ============================================================ */
.mesIDDisplay::before {
    content: 'FILE ID: ';
}

.tokenCounterDisplay::before {
    content: 'WORDAGE:';
}

.mes_timer::before {
    content: 'DURATION:';
}

.timestamp::before {
    content: '[CLASSIFIED: CASE FILE #';
}

.timestamp::after {
    content: ']';
}

.timestamp {
    position: absolute;
    top: 28px;
    left: 50%;
    transform: translateX(-50%);
    white-space: nowrap;
}

.mesIDDisplay, .tokenCounterDisplay, .mes_timer {
    position: absolute;
    top: 53px !important; 
    width: 100px;
    height: 20px;
    line-height: 20px;
    text-align: center;
    background-color: rgba(80, 80, 80, 1) !important;
    border: 1px solid rgba(141, 141, 141, 1) !important;
    color: rgba(202, 202, 202, 1) !important;
    font-size: 10px !important;
    white-space: nowrap;
}

.mesIDDisplay { border-right: none !important; }
.mes_timer { border-left: 1px solid rgba(170, 170, 170, 1) !important; border-right: 1px solid rgba(170, 170, 170, 1) !important; }
.tokenCounterDisplay { border-left: none !important; }

.mes_timer { left: 50%; margin-left: -50px; }
.mesIDDisplay { left: 50%; margin-left: -150px; }
.tokenCounterDisplay { left: 50%; margin-left: 50px; }

.mes_timer:empty, .mes_timer[style*="display: none"] {
    display: none !important;
}

.mes:not(:has(.mes_timer:not(:empty):not([style*="display: none"]))) .mesIDDisplay {
    margin-left: -100px !important;
    border-right: 1px solid #aaa !important;
}

.mes:not(:has(.mes_timer:not(:empty):not([style*="display: none"]))) .tokenCounterDisplay {
    margin-left: 0px !important;
}

/* ============================================================
   5. 功能按钮与交互元素 (Action Buttons & Swipes)
   ============================================================ */
.mes_button, .extraMesButtons .mes_button {
    filter: none !important;
    opacity: 0.7;
}

.mes_edit, .extraMesButtonsHint, .mes_edit_buttons {
    filter: none;
}

.mes_edit::before { content: 'Edit' !important; }
.extraMesButtonsHint::before { content: 'Extra' !important; }

.mes_edit::before, .extraMesButtonsHint::before {
    font-family: "GenWanMin2 TC R";
    font-size: 11px;
    background-color: rgba(44, 44, 44, 1);
    border: 1px solid rgba(131, 131, 131, 1);
    color: rgba(186, 186, 186, 1);
    padding: 2px 8px;
}

.mes_buttons {
    position: absolute;
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
}

.mes_edit_buttons {
    position: absolute;
    bottom: -5px;
    left: 50%;
    transform: translateX(-50%) scale(0.8);
}

/* 翻页图标替换二改by 眠N勿扰老师 */
.swipe_left::before { content: '◀' !important;}
.swipe_left, .swipe_right {
    position: absolute !important;
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    font-size: 14px;
    font-family: "GenWanMin2 TC R";
    color: rgba(93, 93, 93, 1);
}
.swipe_right::before { content: '▶' !important; }
.swipe_right { margin-right: 10px; bottom: 10px; }
.swipe_left { bottom: 7px; margin-left: 10px; }

.swipes-counter {
    position: absolute!important; 
    bottom: 60px;
    right: 17px;
    font-family: "GenWanMin2 TC R";
}

.menu_button, .right_menu_button, .mes_edit_buttons .menu_button {
    background: rgba(83, 83, 83, 1)!important;
    color: rgba(183, 183, 183, 1)!important;
    transition: background-color 0.3s ease, transform 0.2s ease !important;
    border-radius: 0 !important;
}

.menu_button:hover, .right_menu_button:hover {
    background-color: rgba(183, 183, 183, 1)!important;
    color: rgba(83, 83, 83, 1)!important;
    transform: scale(1.05);
}

/* ============================================================
   6. 顶栏样式 (Top Bar Styles)
   ============================================================ */
/* 顶栏图标by墨千尾老师 */
#top-bar {
    background: transparent;
    box-shadow: none;
}

#top-settings-holder .drawer-icon {
    font-size: 18px;
    transition: transform 0.2s ease;
    opacity: 1 !important;
}

#top-settings-holder .drawer-icon:hover, #top-settings-holder .drawer-icon:not(.closedIcon) {
    transform: translateY(2px);
}

/* ============================================================
   7. 输入框与发送表单 (Send Form & Input)
   ============================================================ */
/* 底栏图标by墨千尾老师 */
#send_form {
    position: absolute;
    background: transparent;
    border-radius: 0;
    border: 0;
    bottom: 0;
}

#send_form [class*="fa-"]::before {
    font-size: 18px; 
    opacity: 1 !important;
    color: var(--SmartThemeBodyColor);
}

#send_textarea {
    font-family: "GenWanMin2 TC R";
    background: var(--SmartThemeChatTintColor);
    border-radius: 0;
}

/* 输入框文字by hgu老师 */
#send_textarea::placeholder {
    color: transparent !important;
    opacity: 0 !important;
}

#nonQRFormItems {
    position: relative !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
    content: '[TYPING...]';
    font-size: 12px;
    white-space: nowrap;
    animation: typing-flicker 3.5s ease-in-out infinite;
    position: absolute;
    z-index: 10;
    pointer-events: none;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* 隐藏QR栏二改by 12老师 */
#qr--bar {
    max-height: 0 !important;
    opacity: 0 !important;
    pointer-events: none;
    transition: all 2s !important;
    cubic-bezier(0.175, 0.885, 0.32, 1.275)
}

#send_form:focus-within #qr--bar {
    max-height: 120px !important;
    opacity: 1 !important;
    pointer-events: auto;
}

/* 输入时隐藏除发送键外的按钮二改by N老师 */
#send_form:has(#send_textarea:focus) {
    #leftSendForm, #quickPersonaImg, #quick-reply-rocket-button {
        display: none !important;
    }
}

/* ============================================================
   8. 侧边栏与角色面板 (Nav Panels & Character Select)
   ============================================================ */
#right-nav-panel, #left-nav-panel {
    background-image: url("https://www.transparenttextures.com/patterns/rough-cloth-light.png");
}

.avatar-container.interactable.selected {
    background: rgba(52, 52, 52, 1);
}

.avatar-container.interactable {
    border: 1px solid var(--SmartThemeBorderColor);
    transition: 0.4s ease !important;
    border-radius: 0 !important;
}

.avatar-container.interactable:hover {
    padding: 15px;
}

.character_select.entity_block.flex-container {
    background: rgba(59, 59, 59, 1);
    padding: 0;
    border-radius: 0;
    border: 1px solid rgba(83, 83, 83, 1);
    transition: 0.4s ease !important;
}

.character_select.entity_block.flex-container:hover {
    padding: 15px;
}

#rm_button_selected_ch::before {
    content: 'SUBJECT ID:';
    font-size: 12px;
}

#rm_ch_create_block #avatar_load_preview {
    transition: transform 0.8s ease, width 0.8s ease, height 0.8s ease;
    cursor: pointer;
    object-fit: cover; 
}

#rm_ch_create_block #avatar_load_preview:hover {
    width: 100px !important;
    height: 100px !important;
    transform: scale(1.05);
}

/* ============================================================
   9. 通用UI组件 (UI Component Overrides)
   ============================================================ */
.text_pole, select, input, button, textarea, .select2-selection, .select2-dropdown, .inline-drawer, .drawer-content, .list-group, dialog.popup, .popup-content, .mes_text, #send_form, #send_textarea, #PersonaManagement, #user-settings-block, #rm_extensions_block, #extensionsMenu, #options, #options-content, #select_chat_popup, .select2-selection__choice {
    border-radius: 0 !important;
}

dialog.popup, #select_chat_popup, select, .list-group, .select2-dropdown, #options, #options-content, #extensionsMenu {
    box-shadow: none !important;
}

.text_pole, select, input[type="text"], input[type="number"], input[type="search"], #settingsSearch, .popup textarea, #description_textarea, #firstmessage_textarea, .edit_textarea.mdHotkeys, .reasoning_edit_textarea, .select2-container--default .select2-selection--single, .select2-container--default .select2-selection--multiple {
    padding: 1px;
    background: rgba(42, 42, 42, 1);
}

select option {
    background: transparent !important;
    color: var(--SmartThemeBodyColor) !important;
}

.select2-selection__choice__display, .select2-selection__choice__remove {
    background: none !important;
}

/* ============================================================
   10. 插件与扩展管理 (Extensions & Prompt Manager)
   ============================================================ */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, #completion_prompt_manager_list, .reverse_proxy_warning {
    border-radius: 0 !important;
    background: rgba(23, 23, 23, 1);
}

#completion_prompt_manager_list {
    padding: 0 13px 0 13px;
}

.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled.ui-sortable-handle {
    background-color: rgba(49, 49, 49, 1);
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    margin-top: 3px;
    transition: 0.4s ease !important;
}

.completion_prompt_manager_prompt:hover {
    margin-left: 8px !important;
}

.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #666 !important;
}

.completion_prompt_manager_prompt .fa-asterisk, .completion_prompt_manager_prompt .fa-square-poll-horizontal, .completion_prompt_manager_prompt .fa-syringe, .completion_prompt_manager_prompt .fa-thumb-tack, .fa-xs.fa-solid.fa-robot/* 类名by hy老师 */ {
    color: var(--SmartThemeQuoteColor) !important;
}

/* 类名byMDMA老师 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span, 
#completion_prompt_manager .completion_prompt_manager_header div, 
.prompt_manager_prompt_controls span {
    filter: none !important;
    color: #666;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header {
    transition: 0.4s ease !important;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header:hover {
    margin-top: 5px !important;
}

/* ============================================================
   11. 折叠图标与状态 (Drawer Icons & Chevrons)
   ============================================================ */
.fa-circle-chevron-down::before,
.fa-circle-chevron-up::before,
.inline-drawer-icon.fa-circle-chevron-down::before,
.inline-drawer-icon.fa-circle-chevron-up::before {
    content: '▼' ;
    font-family: "GenWanMin2 TC R";
    color: #bbb !important;
    font-size: 12px;
    display: inline-block;
    transition: transform 0.3s ease-in-out !important;
    padding: 3px;
}

.fa-circle-chevron-down, .inline-drawer-icon.fa-circle-chevron-down {
    transform: scaleY(1) !important;
    transition: transform 0.5s ease-in-out !important;
}

.fa-circle-chevron-up, .inline-drawer-icon.fa-circle-chevron-up {
    transform: scaleY(-1) !important; 
    transition: transform 0.5s ease-in-out !important;
}

/* ============================================================
   12. 通知、复选框与滑块 (Toasts, Checkbox & Slider)
   ============================================================ */
/* 通知美化by serein老师、hy老师 */
#toast-container > .toast { background-image: none !important; }
.toast::before {
    content: '✦';
    position: absolute;
    left: 12px;
    top: 45%;
    transform: translateY(-50%);
    font-size: 30px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}
.toast {
    background: rgba(80, 80, 80, 1) !important;
    border: 1px solid rgba(125, 125, 125, 1);
    border-radius: 0 !important;
    box-shadow: none !important;
    color: rgba(16, 16, 16, 1) !important;
}

/* 滑块样式by墨千尾老师 */
input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    background: transparent !important;
    cursor: pointer;
    filter: none;
}
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 4px; 
    background: rgba(70, 70, 70, 1); 
    border-radius: 3px;
    border: 0;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -8px;
    height: 22px; 
    width: 22px; 
    -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='20' height='20'><text y='17' x='0' font-size='20'>✦</text></svg>");
    mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='20' height='20'><text y='17' x='0' font-size='20'>✦</text></svg>");
    background-color: rgba(159, 159, 159, 1); 
    box-shadow: none;
    transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
    transform: translateY(-2px) scale(1.1) rotate(-15deg);
}

/* 复选框二改by食南瓜者老师 */
input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 14px;
    height: 14px;
    border: 1px solid #666;
    background: transparent;
    transition: all 0.2s ease;
    position: relative;
}
input[type="checkbox"]:checked { background: #555; border-color: 0; }
input[type="checkbox"]::after, input[type="checkbox"]::before { content: none !important; }
input[type="checkbox"]:checked::after {
    content: '✦' !important;
    display: block !important;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: #ddd;
    font-size: 14px;
}
input[type="checkbox"]:hover { border-color: #aaa; }

/* ============================================================
   13. 动画定义 (Keyframes)
   ============================================================ */
@keyframes typing-flicker {
    0%, 100% { opacity: 0.2; }
    50% { opacity: 0.6; }
}
